/* Shape gateway_keys rows for the console (never expose key_hash fully).
   Spend counters come straight from the key row (maintained by the gateway). */
const rows = $input.all().map((i) => i.json).filter((r) => r && r.name);
const now = Date.now();
const r2 = (x) => Math.round(x * 1e6) / 1e6;
const keys = rows.map((r) => ({
  id: r.id,
  name: r.name,
  enabled: r.enabled === 1 || r.enabled === true,
  rate_limit_rpm: Number(r.rate_limit_rpm || 0),
  budget_daily_usd: Number(r.budget_daily_usd || 0),
  budget_monthly_usd: Number(r.budget_monthly_usd || 0),
  spend_24h: (now - (Date.parse(r.spend_24h_at || '') || 0)) <= 24 * 3600 * 1000 ? r2(Number(r.spend_24h || 0)) : 0,
  spend_30d: (now - (Date.parse(r.spend_30d_at || '') || 0)) <= 30 * 24 * 3600 * 1000 ? r2(Number(r.spend_30d || 0)) : 0,
  total_cost: Number(r.total_cost || 0),
  fingerprint: String(r.key_hash || '').slice(0, 10),
  created_at: r.createdAt,
}));
return [{ json: { ok: true, keys } }];

