/* Manage gateway keys — parity with n8n/scripts/keys.mjs.
   Actions: create | enable | disable | set_limit | delete. All writes audit-logged. */
const crypto = require('crypto');
const body = ($('Webhook Keys Manage').first().json.body) || {};
const action = String(body.action || '');
const name = String(body.name || '').trim();

const base = 'http://localhost:5678/api/v1';
const api = (method, path, qs, payload) => this.helpers.httpRequest({
  method, url: base + path,
  headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' },
  qs, body: payload,
});
const filter = (col, value) => JSON.stringify({ type: 'and', filters: [{ columnName: col, condition: 'eq', value }] });
const filterObj = (col, value) => ({ type: 'and', filters: [{ columnName: col, condition: 'eq', value }] });
const tableId = async (tname) => {
  const list = await api('GET', '/data-tables', { limit: 100 });
  const t = (list.data || []).find((x) => x.name === tname);
  if (!t) throw new Error(tname + ' table not found');
  return t.id;
};
const audit = async (act, detail) => {
  try {
    const t = await tableId('admin_audit');
    await api('POST', `/data-tables/${t}/rows`, null, { data: [{ action: act, target: name || '', detail: String(detail || '').slice(0, 300) }] });
  } catch (e) { /* audit best-effort */ }
};
const bad = (status, code, message) => [{ json: { __error: true, status, openai_error: { error: { message, type: 'invalid_request_error', code } } } }];

if (!name || !/^[\w.-]{1,40}$/.test(name)) return bad(400, 'invalid_name', 'name must be 1-40 chars: letters, digits, _ . -');
if (!['create', 'enable', 'disable', 'set_limit', 'delete', 'set_budget'].includes(action)) return bad(400, 'unknown_action', 'unknown action: ' + action);

const id = await tableId('gateway_keys');
const rows = await api('GET', `/data-tables/${id}/rows`, { filter: filter('name', name) });
const existing = (rows.data || [])[0] || null;

if (action === 'create') {
  if (existing) return bad(409, 'already_exists', 'key already exists: ' + name);
  const rpm = Number(body.rate_limit_rpm || 0);
  if (!Number.isFinite(rpm) || rpm < 0) return bad(400, 'invalid_rpm', 'rate_limit_rpm must be >= 0');
  const bd = Number(body.budget_daily_usd || 0);
  const bm = Number(body.budget_monthly_usd || 0);
  if (!Number.isFinite(bd) || bd < 0 || !Number.isFinite(bm) || bm < 0) return bad(400, 'invalid_budget', 'budgets must be >= 0');
  const raw = 'sk-gw-' + crypto.randomBytes(24).toString('hex');
  const keyHash = crypto.createHash('sha256').update(raw).digest('hex');
  await api('POST', `/data-tables/${id}/rows`, null, { data: [{ key_hash: keyHash, name, enabled: 1, rate_limit_rpm: rpm, budget_daily_usd: bd, budget_monthly_usd: bm, total_cost: 0 }] });
  await audit('key.create', 'rpm=' + rpm);
  return [{ json: { ok: true, action, name, raw_key: raw, rate_limit_rpm: rpm, note: 'raw key shown once — store it now' } }];
}

if (!existing) return bad(404, 'not_found', 'key not found: ' + name);

if (action === 'enable' || action === 'disable') {
  await api('PATCH', `/data-tables/${id}/rows/update`, null, { filter: filterObj('name', name), data: { enabled: action === 'enable' ? 1 : 0 } });
  await audit('key.' + action, '');
  return [{ json: { ok: true, action, name } }];
}

if (action === 'set_limit') {
  const rpm = Number(body.rate_limit_rpm);
  if (!Number.isFinite(rpm) || rpm < 0) return bad(400, 'invalid_rpm', 'rate_limit_rpm must be >= 0');
  await api('PATCH', `/data-tables/${id}/rows/update`, null, { filter: filterObj('name', name), data: { rate_limit_rpm: rpm } });
  await audit('key.set_limit', 'rpm=' + rpm);
  return [{ json: { ok: true, action, name, rate_limit_rpm: rpm } }];
}

if (action === 'set_budget') {
  const bd2 = Number(body.budget_daily_usd);
  const bm2 = Number(body.budget_monthly_usd);
  if (!Number.isFinite(bd2) || bd2 < 0 || !Number.isFinite(bm2) || bm2 < 0) return bad(400, 'invalid_budget', 'budget_daily_usd / budget_monthly_usd must be >= 0');
  await api('PATCH', `/data-tables/${id}/rows/update`, null, { filter: filterObj('name', name), data: { budget_daily_usd: bd2, budget_monthly_usd: bm2 } });
  await audit('key.set_budget', 'daily=' + bd2 + ' monthly=' + bm2);
  return [{ json: { ok: true, action, name, budget_daily_usd: bd2, budget_monthly_usd: bm2 } }];
}

const deleted = await api('DELETE', `/data-tables/${id}/rows/delete`, { filter: filter('name', name), returnData: true });
const n = Array.isArray(deleted) ? deleted.length : (deleted && deleted.data ? deleted.data.length : 0);
await audit('key.delete', 'removed=' + n);
return [{ json: { ok: true, action, name, removed: n } }];

