/* Model registry: aliases & pricing parsed LIVE from the Chat Gateway workflow,
   plus 30d usage aggregated from recent chat_executions rows. */
const apiCall = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const list = await apiCall('GET', '/workflows', { limit: 100 });
const gw = (list.data || []).find((w) => w.name === 'Chat Gateway');
let aliases = [];
const pricing = {};
let defaultModel = null;
if (gw) {
  const pv = (gw.nodes.find((n) => n.name === 'Parse & Validate') || {}).parameters || {};
  const sl = (gw.nodes.find((n) => n.name === 'Prep Success Log') || {}).parameters || {};
  const code = String(pv.jsCode || '');
  const price = String(sl.jsCode || '');
  const reAlias = /'([\w-]+)':\s*\{\s*upstream:\s*'([\w-]+)',\s*tools:\s*(true|false)\s*\}/g;
  let m;
  while ((m = reAlias.exec(code))) aliases.push({ alias: m[1], upstream: m[2], tools: m[3] === 'true' });
  const reDefault = /const DEFAULT_MODEL = '([\w-]+)';/.exec(code);
  defaultModel = reDefault ? reDefault[1] : null;
  const rePrice = /'([\w-]+)':\s*\{\s*input:\s*([\d.]+),\s*cache_hit:\s*([\d.]+),\s*output:\s*([\d.]+)\s*\}/g;
  while ((m = rePrice.exec(price))) pricing[m[1]] = { input: Number(m[2]), cache_hit: Number(m[3]), output: Number(m[4]) };
}
const execRows = $input.all().map((i) => i.json).filter((r) => r && r.model);
const now = Date.now();
const cut30 = now - 30 * 24 * 3600 * 1000;
const usage = {};
for (const r of execRows) {
  const t = Date.parse(r.createdAt || '');
  if (!Number.isFinite(t) || t < cut30) continue;
  const k = r.model;
  if (!usage[k]) usage[k] = { calls: 0, cost: 0 };
  usage[k].calls += 1;
  usage[k].cost += Number(r.cost_usd) || 0;
}
const r2 = (x) => Math.round(x * 1e6) / 1e6;
const models = aliases.map((a) => ({
  alias: a.alias,
  upstream: a.upstream,
  tools: a.tools,
  pricing: pricing[a.upstream] || null,
  calls_30d: ((usage[a.alias] || {}).calls) || 0,
  cost_30d: r2(((usage[a.alias] || {}).cost) || 0),
  is_default: a.alias === defaultModel,
}));
return [{ json: { ok: true, default_model: defaultModel, models, note: 'aliases & pricing parsed live from the Chat Gateway workflow; usage from last 1000 executions' } }];

